// ===== KONFIG: eigene Daten & Defaults – hier pflegen =====
const CONFIG = {
  an: {
    an_firma: 'Philipp Niestroj Software Engineering',
    an_strasse: 'Neckarstraße 2',
    an_plz_ort: '84036 Landshut',
    an_ort: 'Landshut',
    an_vertreter: 'Philipp Niestroj',
    an_email: 'contact@philippniestroj.com',
    an_website: 'www.philippniestroj.com',
    an_telefon: '+49 1520 8880466',
    an_bank: 'Kontoinhaber: Philipp Niestroj\nIBAN: DE.. .... .... .... .... ..  ← eintragen\nBIC: ........'
  },
  defaults: {
    zahlungsziel_tage: '14',
    kuendigungsfrist: 'vier Wochen zum Monatsende',
    vertragsstrafe_min: '5.000,00',
    vertragsstrafe_max: '25.000,00',
    abwerbe_strafe_monate: 'drei',
    werk_anlagen: '–'
  },
  vertraege: {
    'nda':             { template: 'nda.html',             titel: 'Geheimhaltungsvereinbarung (NDA)', pflicht: ['projekt_gegenstand', 'gespraeche_seit'] },
    'werkvertrag':     { template: 'werkvertrag.html',     titel: 'Werkvertrag',                      pflicht: ['werk_beschreibung', 'fertigstellung_datum', 'abnahme_person', 'festpreis'] },
    'dienstvertrag':   { template: 'dienstvertrag.html',   titel: 'Dienstvertrag (Beratung)',         pflicht: ['beratung_gegenstand', 'beratung_bereich', 'beratung_leistungen', 'beginn_datum', 'stundensatz', 'tagessatz'] },
    'freie-mitarbeit': { template: 'freie-mitarbeit.html', titel: 'Honorarvertrag (freie Mitarbeit)', pflicht: ['taetigkeit_rolle', 'taetigkeit_bereich', 'taetigkeit_aufgaben', 'beginn_datum', 'stundensatz', 'tagessatz'] }
  }
};

const b = $input.first().json.body || $input.first().json;
const art = b.vertrag;
const def = CONFIG.vertraege[art];
if (!def) throw new Error(`Unbekannter Vertragstyp: ${art}. Erlaubt: ${Object.keys(CONFIG.vertraege).join(', ')}`);
if (!b.client_id) throw new Error('client_id fehlt');

const felder = { ...CONFIG.an, ...CONFIG.defaults, ...(b.felder || {}) };
const fehlen = def.pflicht.filter(k => !felder[k]);
if (fehlen.length) throw new Error(`Pflichtfelder fehlen: ${fehlen.join(', ')}`);

return [{ json: { vertrag: art, titel: def.titel, templateFile: def.template, client_id: b.client_id, felder } }];

// Die get_client-Antwort auf die Vertragsfelder legen.
// Feldnamen links gehören den Templates, rechts der SoloOps-Client.
const base = $('Eingabe prüfen & Konfig').first().json;
const c = $input.first().json;

// In SoloOps ist `name` die Person und `company` die Firma; ein Kunde ohne
// Firma ist eine Einzelperson, dann steht der Name in beiden Zeilen.
const kunde = {
  kunde_firma:     c.company || c.name || null,
  kunde_strasse:   c.street || null,
  kunde_plz_ort:   (c.zip && c.city) ? `${c.zip} ${c.city}` : null,
  kunde_ort:       c.city || null,
  kunde_vertreter: c.name || null,
  kunde_email:     c.email || null
};

// Fehlendes beim Namen nennen: „Kundendaten unvollständig" schickt einen auf
// die Suche, „Straße, PLZ, Ort fehlen" sagt, was zu tun ist.
const LABEL = {
  kunde_firma: 'Firma/Name', kunde_strasse: 'Straße', kunde_plz_ort: 'PLZ und Ort',
  kunde_ort: 'Ort', kunde_vertreter: 'Ansprechpartner', kunde_email: 'E-Mail'
};
const fehlt = Object.entries(kunde).filter(([, v]) => !v).map(([k]) => LABEL[k]);
if (fehlt.length) {
  throw new Error(`Beim Kunden ${c.name || c.id} fehlt: ${[...new Set(fehlt)].join(', ')} — in SoloOps unter Kunden ergänzen.`);
}

const felder = { ...base.felder, ...kunde };

const zohoCreatePayload = {
  requests: {
    request_name: `${base.titel} – ${kunde.kunde_firma}`,
    is_sequential: false,
    expiration_days: 15,
    actions: [
      { recipient_name: kunde.kunde_vertreter, recipient_email: kunde.kunde_email, action_type: 'SIGN', signing_order: 0, verify_recipient: false },
      { recipient_name: felder.an_vertreter,   recipient_email: felder.an_email,   action_type: 'SIGN', signing_order: 1, verify_recipient: false }
    ]
  }
};

return [{ json: { ...base, felder, kunde_email: kunde.kunde_email, kunde_firma: kunde.kunde_firma, zohoCreatePayload } }];

const felder = $('Kundendaten mappen').first().json.felder;
const bin = $input.first().binary.data;
const html = Buffer.from(bin.data, 'base64').toString('utf-8');

const esc = (v) => String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const missing = [];
const filled = html.replace(/\{\{(\w+)\}\}/g, (m, k) => {
  if (felder[k] === undefined || felder[k] === '') { missing.push(k); return m; }
  return esc(felder[k]);
});
if (missing.length) throw new Error('Platzhalter ohne Wert: ' + [...new Set(missing)].join(', '));

return [{ json: {}, binary: { data: { data: Buffer.from(filled, 'utf-8').toString('base64'), mimeType: 'text/html', fileName: 'index.html' } } }];

// Signaturfelder auf der Unterschriftenseite (= letzte Seite) platzieren.
// Die Templates haben dort zwei feste Boxen – Koordinaten in PDF-Punkten (A4 = 595 x 842).
// Beim ersten Testversand prüfen und ggf. um ein paar Punkte verschieben.
const res = $input.first().json;
const req = res.requests;
if (!req) throw new Error('Unerwartete Zoho-Antwort: ' + JSON.stringify(res).slice(0, 500));

const doc = req.document_ids[0];
// total_pages kommt als String zurück; 0-basierte Seitennummer.
const lastPage = Number(doc.total_pages || 1) - 1;

const COORDS = { y: 168, width: 225, height: 55, xKunde: 55, xIch: 315 };

const actions = req.actions.map((a, i) => ({
  action_id: a.action_id,
  action_type: a.action_type,
  recipient_name: a.recipient_name,
  recipient_email: a.recipient_email,
  signing_order: a.signing_order,
  verify_recipient: false,
  fields: [{
    // field_category gehört dazu: ohne sie legt Zoho das Feld als Textfeld an
    // und der Empfänger bekommt eine Zeile statt einer Unterschrift.
    field_category: 'image',
    field_type_name: 'Signature',
    field_name: i === 0 ? 'Unterschrift Auftraggeber' : 'Unterschrift Auftragnehmer',
    field_label: i === 0 ? 'Auftraggeber' : 'Auftragnehmer',
    action_id: a.action_id,
    document_id: doc.document_id,
    is_mandatory: true,
    page_no: lastPage,
    x_coord: i === 0 ? COORDS.xKunde : COORDS.xIch,
    y_coord: COORDS.y,
    abs_width: COORDS.width,
    abs_height: COORDS.height
  }]
}));

return [{ json: { request_id: req.request_id, request_name: req.request_name, submitPayload: { requests: { actions } } } }];
